{"filename": "test_ca_10_dedupe.py", "content": "import os
import importlib.util
import pytest

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
unique_preserve_order = target.unique_preserve_order


def test_exact_duplicates_removed_keeping_first():
    assert unique_preserve_order(["x", "y", "x"]) == ["x", "y"]


def test_case_variants_are_duplicates():
    # Spec: later entries differing only by case are duplicates.
    result = unique_preserve_order(["Apple", "apple", "APPLE", "banana"])
    assert result == ["Apple", "banana"], f"got {result}"


def test_first_occurrence_casing_preserved():
    result = unique_preserve_order(["b", "A", "a", "B"])
    assert result == ["b", "A"], f"got {result}"


def test_first_seen_order_preserved():
    assert unique_preserve_order(["c", "a", "b", "a", "c"]) == ["c", "a", "b"]


def test_no_duplicates_returns_same_sequence():
    assert unique_preserve_order(["one", "two", "three"]) == ["one", "two", "three"]


def test_empty_list_returns_empty():
    assert unique_preserve_order([]) == []


def test_non_list_raises_type_error():
    with pytest.raises(TypeError):
        unique_preserve_order(("a", "b"))


def test_non_string_item_raises_type_error():
    with pytest.raises(TypeError):
        unique_preserve_order(["a", 1])
"}

