import os
import importlib.util
import pytest

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
compact_whitespace = target.compact_whitespace


def test_strips_leading_and_trailing_whitespace():
    assert compact_whitespace(["  hello  ", "\tworld\n"]) == ["hello", "world"]


def test_whitespace_only_lines_omitted():
    assert compact_whitespace(["a", "   ", "\t", "b"]) == ["a", "b"]


def test_empty_string_omitted():
    assert compact_whitespace(["", "x", ""]) == ["x"]


def test_order_of_non_empty_lines_preserved():
    assert compact_whitespace(["c", " b ", "a"]) == ["c", "b", "a"]


def test_internal_whitespace_not_altered():
    # Spec only says strip each line; interior spacing is not collapsed.
    assert compact_whitespace(["  a  b  "]) == ["a  b"]


def test_all_blank_returns_empty():
    assert compact_whitespace(["", "  ", "\n"]) == []


def test_empty_input_returns_empty():
    assert compact_whitespace([]) == []


def test_duplicates_are_kept():
    assert compact_whitespace(["x", " x "]) == ["x", "x"]


def test_non_list_raises_type_error():
    with pytest.raises(TypeError):
        compact_whitespace("abc")


def test_non_string_item_raises_type_error():
    with pytest.raises(TypeError):
        compact_whitespace(["a", None])

